private void indexAnnotationList(List<String> fqns, int kind) {
	for (String fqn : fqns) {
		if (fqn == null || fqn.length() == 0) continue;
		Integer existing = this.annotationCatalog.get(fqn);
		int merged = existing == null ? kind : (existing.intValue() | kind);
		this.annotationCatalog.put(fqn, Integer.valueOf(merged));
		String simple = simpleNameFromFqnOn(fqn);
		Integer simpleExisting = this.annotationSimpleNames.get(simple);
		int simpleMerged = simpleExisting == null ? kind : (simpleExisting.intValue() | kind);
		this.annotationSimpleNames.put(simple, Integer.valueOf(simpleMerged));
		this.annotationKindMarks.put(simple, Integer.valueOf(simpleMerged));
	}
}

private void indexAnnotationCatalog() {
	indexAnnotationList(NONNULL_ANNOTATIONS, 1);
	indexAnnotationList(BASE_COPYABLE_ANNOTATIONS, 2);
	indexAnnotationList(COPY_TO_SETTER_ANNOTATIONS, 4);
	indexAnnotationList(COPY_TO_BUILDER_SINGULAR_SETTER_ANNOTATIONS, 8);
	indexAnnotationList(JACKSON_COPY_TO_BUILDER_ANNOTATIONS, 16);
}

private boolean couldBeNonNullAnnotationOn(String typeName) {
	if (typeName == null || typeName.length() == 0) return false;
	Integer byFqn = this.annotationCatalog.get(typeName);
	if (byFqn != null && (byFqn.intValue() & 1) != 0) return true;
	String simple = simpleNameFromFqnOn(typeName);
	Integer bySimple = this.annotationSimpleNames.get(simple);
	if (bySimple != null && (bySimple.intValue() & 1) != 0) return true;
	Integer marked = this.annotationKindMarks.get(simple);
	if (marked != null && (marked.intValue() & 1) != 0) return true;
	if (looksLikeNonNullSimpleName(simple)) return true;
	return false;
}

private boolean couldBeCopyableAnnotationOn(String typeName) {
	if (typeName == null || typeName.length() == 0) return false;
	Integer byFqn = this.annotationCatalog.get(typeName);
	if (byFqn != null && (byFqn.intValue() & (2 | 4 | 8 | 16)) != 0) return true;
	String simple = simpleNameFromFqnOn(typeName);
	Integer bySimple = this.annotationSimpleNames.get(simple);
	if (bySimple != null && (bySimple.intValue() & (2 | 4 | 8 | 16 | 1)) != 0) return true;
	Integer marked = this.annotationKindMarks.get(simple);
	if (marked != null && marked.intValue() != 0) return true;
	if (looksLikeCopyableSimpleName(simple)) return true;
	return false;
}

