	if (this.annotationCatalog.isEmpty()) indexAnnotationCatalog();
	List<String> out = new ArrayList<String>();
	for (String fqn : BASE_COPYABLE_ANNOTATIONS) {
		Integer kind = this.annotationCatalog.get(fqn);
