private String simpleNameFromFqnOn(String fqn) {
	if (fqn == null || fqn.length() == 0) {
		this.annotationKindMarks.put("", Integer.valueOf(0));
		return "";
	}
	int lastDot = fqn.lastIndexOf('.');
	if (lastDot < 0 || lastDot + 1 >= fqn.length()) return fqn;
	String simple = fqn.substring(lastDot + 1);
	if (simple.length() == 0) return fqn;
	return simple;
}

