				int lastIndex = annType.lastIndexOf('.');
				disallowed.add(lastIndex == -1 ? annType : annType.substring(lastIndex + 1));
			}
		}
	}

	int size = disallowed == null ? 0 : disallowed.size();
	if (size == 0) return;
